// QA joint film-path acceptance (film-name-parsing box 3.2, Tier 1). REAL
// plugin subprocesses over a REAL fixture library: a serial directory holding
// the two real movie files as direct videos (numberless filenames → the film
// path) plus a control directory with one numbered episode (the episode path
// must keep working beside it). The full pipeline runs for real — scan
// (serial-scanner subprocess + ffprobe) → the async queue drains serial-parser
// → item documents settle ready — and the assertions read the served item
// documents exactly as the SPA would: sources.serial-parser for the parsed
// facts, _view.title for the display title.
//
// The two film names are the real release names as string literals (the
// no-/Volumes discipline: nothing here touches a real collection). Every
// helper is qaFilm-prefixed to stay collision-free in package mellifera_test;
// the qa_serial harness (buildBinary/qaSerialStartServer/scanLibrary/…) is
// reused as-is.
package itest

import (
	"net/http"
	"os/exec"
	"path/filepath"
	"reflect"
	"testing"
)

// Fixture identity constants. The serial directory and control names are
// independent of the plugin suites' fixtures (no-coincidence discipline);
// the two film filenames are the acceptance's real release names verbatim.
const (
	qaFilmDir      = "QA Joint Film Vault"
	qaFilmDemonRel = qaFilmDir + "/Demon.Slayer.Kimetsu.No.Yaiba.Infinity.Castle.1080p.CR-Cassu.mkv"
	qaFilmChainRel = qaFilmDir + "/Chainsaw.Man.The.Movie.Reze.Arc.2025.1080p.AMZN.WEB-DL.H.264-EniaHD.mkv"
	qaFilmCtrlDir  = "Show"
	qaFilmCtrlRel  = qaFilmCtrlDir + "/Show.S01E02.1080p.mkv"
)

// TestQAFilm_JointItemParse is the film-path Tier-1 joint contract: film
// filenames enrich with their clean titles and release fields — and NEVER a
// season or episode key — through the real subprocess pipeline, while a
// numbered control episode in the same library keeps its season/episode
// parse (the film path must not bleed into the episode path).
func TestQAFilm_JointItemParse(t *testing.T) {
	if testing.Short() {
		t.Skip("QA film joint test: skips under -short (builds binaries + subprocesses)")
	}
	if _, err := exec.LookPath("ffprobe"); err != nil {
		t.Skip("ffprobe not on PATH — fixture videos cannot be probed; skipping the film joint test (INV4: optional binary)")
	}

	tmp := t.TempDir()
	serverBin := buildBinary(t, tmp, "qa-film-server", "./cmd/mellifera")
	baseScannerBin := buildBinary(t, tmp, "qa-film-basescanner", "./plugins/base-scanner")
	tvParserBin := buildBinary(t, tmp, "qa-film-tvparser", "./plugins/tv-parser")
	imageEnricherBin := buildBinary(t, tmp, "qa-film-imageenricher", "./plugins/image-enricher")
	serialScannerBin := buildBinary(t, tmp, "qa-film-scanner", "./plugins/serial-scanner")
	serialParserBin := buildBinary(t, tmp, "qa-film-parser", "./plugins/serial-parser")
	frameGrabberBin := buildBinary(t, tmp, "qa-film-grabber", "./plugins/frame-grabber")

	root := qaFilmWriteFixtures(t)

	// The stub upstream rides the shared serial harness (the helper passes
	// MELLIFERA_SHIKIMORI_UPSTREAM through to the server env): the vault's
	// series row drives a real shikimori search, and the no-network rule pins
	// it to the stub — a non-anime title 404s there and the row still settles
	// ready, which is all this item-level contract waits for.
	up := qaSerialStartUpstream(t)
	srv := qaSerialStartServer(t, qaSerialServerBins{
		server: serverBin, baseScanner: baseScannerBin, tvParser: tvParserBin,
		imageEnricher: imageEnricherBin, serialScanner: serialScannerBin,
		serialParser: serialParserBin, frameGrabber: frameGrabberBin,
	}, up.baseURL, tmp, "qa-film-admin-token")
	client := &http.Client{Timeout: httpTimeout}

	lib := qaSerialCreateLibrary(t, client, srv.baseURL, "qa-film-admin-token", root, "QA Film Joint")
	res := scanLibrary(t, client, srv.baseURL, "qa-film-admin-token", lib)
	// 2 serial records (the film vault + the control directory) + 3 probed
	// episode items (both films are direct videos of the vault — numberless
	// episode candidates at the scanner — plus the control's one episode).
	if res.Discovered != 5 || res.Persisted != 5 {
		t.Fatalf("QA film library: scan discovered=%d persisted=%d, want 5/5 (2 serial records + 3 episode items); warnings=%v",
			res.Discovered, res.Persisted, res.Warnings)
	}
	if len(res.Warnings) != 0 {
		t.Errorf("QA film library: warnings = %v, want none (no deep videos)", res.Warnings)
	}

	// --- drain: every series and item row settles ready ---
	qaSerialWaitSettled(t, client, srv.baseURL, "qa-film-admin-token", lib)

	// The two film items: sources.serial-parser carries EXACTLY the parsed
	// title plus the release fields the filename carries — never a season or
	// episode key — and _view.title projects the parsed title (the SPA's
	// display value) from serial-parser.
	for _, tc := range []struct {
		rel  string
		want map[string]any // the EXACT namespace content, field by field
	}{
		{
			rel: qaFilmDemonRel,
			want: map[string]any{
				"title":      "Demon Slayer Kimetsu No Yaiba Infinity Castle",
				"resolution": "1080p",
			},
		},
		{
			rel: qaFilmChainRel,
			want: map[string]any{
				"title":      "Chainsaw Man The Movie Reze Arc 2025",
				"resolution": "1080p",
				"source":     "web-dl",
				"codec":      []any{"h.264"},
				"year":       float64(2025),
			},
		},
	} {
		it := qaSerialItemByRel(t, client, srv.baseURL, "qa-film-admin-token", lib, tc.rel)
		doc := parseAsyncDoc(t, it.Document)
		ns := doc.Sources["serial-parser"]
		if ns == nil {
			t.Errorf("%q: sources.serial-parser missing (the film path must apply to a numberless video in a serial directory)", tc.rel)
			continue
		}
		if len(ns) != len(tc.want) {
			t.Errorf("%q: sources.serial-parser = %v, want exactly %v (%d fields)", tc.rel, ns, tc.want, len(tc.want))
		}
		for field, want := range tc.want {
			switch want := want.(type) {
			case string:
				if got := qaSerialStr(ns, field); got != want {
					t.Errorf("%q: sources.serial-parser[%q] = %v, want %q", tc.rel, field, ns[field], want)
				}
			default: // year float64, codec []any — DeepEqual: []any is uncomparable with ==
				if got := ns[field]; !reflect.DeepEqual(got, want) {
					t.Errorf("%q: sources.serial-parser[%q] = %v, want %v", tc.rel, field, got, want)
				}
			}
		}
		for _, never := range []string{"season", "episode"} {
			if _, ok := ns[never]; ok {
				t.Errorf("%q: film namespace carries %q: %v (never fabricated on the film path)", tc.rel, never, ns)
			}
		}
		viewTitle := doc.View["title"]
		if got := qaSerialStr(viewTitle, "value"); got != tc.want["title"] {
			t.Errorf("%q: _view.title.value = %q, want the parsed title %q", tc.rel, got, tc.want["title"])
		}
		if got := qaSerialStr(viewTitle, "source"); got != "serial-parser" {
			t.Errorf("%q: _view.title.source = %q, want serial-parser", tc.rel, got)
		}
	}

	// The control episode keeps the episode path: season 1 / episode 2 from
	// its SxxExx token, untouched by the film fallthrough living beside it.
	ctrl := qaSerialItemByRel(t, client, srv.baseURL, "qa-film-admin-token", lib, qaFilmCtrlRel)
	ctrlDoc := parseAsyncDoc(t, ctrl.Document)
	ctrlNs := ctrlDoc.Sources["serial-parser"]
	if ctrlNs == nil {
		t.Fatalf("%q: sources.serial-parser missing (the control episode must still parse)", qaFilmCtrlRel)
	}
	if s, e := asyncInt(ctrlNs, "season"), asyncInt(ctrlNs, "episode"); s != 1 || e != 2 {
		t.Errorf("%q: parser season/episode = %v/%v, want 1/2 (the numbered episode keeps its own parse)", qaFilmCtrlRel, ctrlNs["season"], ctrlNs["episode"])
	}
	if !asyncStageHas(ctrlDoc.Stages, "serial-parser", "ok") {
		t.Errorf("%q: _stages = %v, want a {serial-parser ok} stage", qaFilmCtrlRel, ctrlDoc.Stages)
	}
}

// qaFilmWriteFixtures builds the film-joint library: one serial directory
// holding the two real movie files as direct videos, and one control
// directory with a single numbered episode.
func qaFilmWriteFixtures(t *testing.T) string {
	t.Helper()
	root := t.TempDir()
	qaSerialMedia(t, filepath.Join(root, qaFilmDemonRel))
	qaSerialMedia(t, filepath.Join(root, qaFilmChainRel))
	qaSerialMedia(t, filepath.Join(root, qaFilmCtrlRel))
	return root
}
